import type { StaffingContactSource } from '~/client';

interface SourceEntry {
  label: string;
}

export const staffingContactSourceConfig: Record<StaffingContactSource, SourceEntry> = {
  csv_import: { label: 'CSV Import' },
  referral: { label: 'Referral' },
  user_registration: { label: 'User Registration' },
};

export const staffingContactSourceValues = Object.keys(staffingContactSourceConfig) as [
  StaffingContactSource,
  ...StaffingContactSource[],
];

export function getStaffingContactSource(source: StaffingContactSource): SourceEntry {
  return staffingContactSourceConfig[source] ?? { label: snakeCaseToCapitalizedCase(source) };
}

export const sourceOptions: SelectItem<StaffingContactSource>[] = Object.entries(staffingContactSourceConfig).map(
  ([value, { label }]) => ({ name: label, value: value as StaffingContactSource })
);
